//! The actual same-actor receiver selects this additional closed profile.
//! The original scope and Root stream checks remain the only lane authority.

use std::sync::Arc;

use super::*;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_gate::SameActorPhaseGate;

impl AgentdLearningCheckpointClientV1 {
    pub(crate) fn from_original_same_actor_stream_until(
        stream: UnixStream,
        peer: AgentdRootAuthorityPeer,
        root_pidfd: OwnedFd,
        initial: LearningIterationSnapshotV1,
        timeout: Duration,
        scope: FrozenLearningScopeV2,
        gate: &Arc<SameActorPhaseGate>,
    ) -> Result<Self, Error> {
        let mut closing = CloseSameActorPhaseOnDrop::new(gate);
        gate.require_open()
            .map_err(|_| Error::Store(AuthorityTrustError::Unavailable))?;
        scope.validate_snapshot(&initial).map_err(Error::Snapshot)?;
        let expected =
            LearningIterationCoordinatorV1::new(initial.request.clone(), initial.owners.clone())
                .map_err(Error::Snapshot)?;
        if expected.snapshot() != &initial {
            return Err(Error::WrongScope);
        }
        // Retain this exact connected stream before transferring it to the
        // original Root-pidfd constructor. No later remaining time is minted.
        let phase = gate
            .retain_required_original_stream(&stream)
            .map_err(|_| Error::Store(AuthorityTrustError::Unavailable))?;
        let transport = RootObservationStream::from_stream_until(
            stream,
            peer,
            root_pidfd,
            timeout,
            gate.deadline().instant(),
        )
        .map_err(|_| Error::Store(AuthorityTrustError::Unavailable))?;
        let client = Self {
            channel: Mutex::new(Some(Channel {
                transport,
                next_request_id: 1,
            })),
            initial,
            scope: Some(scope),
            phase: Some(phase),
        };
        client.require_original_phase(/*mutation*/ false)?;
        closing.disarm();
        Ok(client)
    }

    pub(super) fn original_phase_failure_scope(&self) -> Option<CloseSameActorPhaseOnDrop> {
        self.phase
            .as_ref()
            .map(|phase: &RequiredSameActorPhaseChannel| phase.failure_scope())
    }

    pub(super) fn require_original_phase(&self, mutation: bool) -> Result<(), Error> {
        if let Some(phase) = &self.phase {
            let phase: &RequiredSameActorPhaseChannel = phase;
            phase.require_open().map_err(|_| {
                if mutation {
                    Error::CommitUncertain(AuthorityTrustError::Unavailable)
                } else {
                    Error::Store(AuthorityTrustError::Unavailable)
                }
            })?;
        }
        Ok(())
    }
}

//! One actual phase receiver supplies the original transport and its retained
//! same-stream shutdown guard. It does not expose a factory from public pins.

use super::*;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;

impl AgentdRootQ24ModelFactoryV1 {
    /// The private receiver retains the required guard from the very socket
    /// used for from_stream_until at gate.deadline().instant(), then transfers
    /// both here. Only the original successful Observe completes construction.
    pub(crate) async fn from_original_same_actor_handoff(
        transport: RootObservationStream,
        profile: HostAuthorityQ24ModelFactoryProfileV1,
        initial: LearningIterationSnapshotV1,
        scope: FrozenLearningScopeV2,
        spawn_generation: u64,
        files: (File, File),
        phase: RequiredSameActorPhaseChannel,
    ) -> Result<Self, AgentdError> {
        let mut closing = phase.failure_scope();
        phase.require_open().map_err(refused)?;
        let (journal, witness) = files;
        profile.require_files(&journal, &witness)?;
        let mut factory = Self {
            transport: Some(transport),
            next_request_id: 1,
            profile,
            initial,
            scope,
            generation: Generation::new(spawn_generation).map_err(refused)?,
            files: Some((journal, witness)),
            owner: None,
            fenced: false,
            phase: Some(phase),
        };
        factory.exchange(Command::Observe).await?;
        factory.require_original_phase()?;
        closing.disarm();
        Ok(factory)
    }

    pub(super) fn original_phase_failure_scope(&self) -> Option<CloseSameActorPhaseOnDrop> {
        self.phase
            .as_ref()
            .map(|phase: &RequiredSameActorPhaseChannel| phase.failure_scope())
    }

    pub(super) fn require_original_phase(&self) -> Result<(), AgentdError> {
        if let Some(phase) = &self.phase {
            let phase: &RequiredSameActorPhaseChannel = phase;
            phase.require_open().map_err(refused)?;
        }
        Ok(())
    }
}

//! Same-UID framing and shared-close components. The private client fixture
//! exercises actual UDS/pidfd and FileCas custody; it does not qualify the
//! Root-only constructor, a business snapshot, or a complete phase deployment.

use super::*;
use crate::same_actor_q24_phase_gate::RequiredSameActorPhaseChannel;
use crate::same_actor_q24_phase_gate::SameActorPhaseDeadline;
use crate::same_actor_q24_phase_gate::SameActorPhaseGate;
use codex_hepta_learning_artifacts::LearningUpdateScopeV2;

fn current_uid() -> u32 {
    // SAFETY: reads this test process's kernel credential without changing it.
    unsafe { libc::geteuid() }
}

struct PhaseClient {
    client: Arc<AgentdLearningCheckpointClientV1>,
    server: Option<UnixStream>,
    gate: Arc<SameActorPhaseGate>,
    _other: RequiredSameActorPhaseChannel,
    other_peer: UnixStream,
}

fn phase_client(
    initial: &LearningIterationSnapshotV1,
    scope: FrozenLearningScopeV2,
) -> PhaseClient {
    let gate = SameActorPhaseGate::from_original_deadline(
        SameActorPhaseDeadline::at_original_service_start(Duration::from_secs(10)).unwrap(),
    )
    .unwrap();
    let (stream, server) = UnixStream::pair().unwrap();
    let phase = gate.retain_required_original_stream(&stream).unwrap();
    // This same-UID transport is only the framing fixture. Until construction
    // remains the separate Root-only production entry and its own tests.
    let transport = RootObservationStream::from_stream_for_uid(
        stream,
        peer(),
        pidfd(),
        Duration::from_millis(500),
        Duration::from_secs(5),
        current_uid(),
    )
    .unwrap();
    let (other, other_peer) = UnixStream::pair().unwrap();
    let other = gate.retain_required_original_stream(&other).unwrap();
    other_peer
        .set_read_timeout(Some(Duration::from_secs(2)))
        .unwrap();
    PhaseClient {
        client: Arc::new(AgentdLearningCheckpointClientV1 {
            channel: Mutex::new(Some(Channel {
                transport,
                next_request_id: 1,
            })),
            initial: initial.clone(),
            scope: Some(scope),
            phase: Some(phase),
        }),
        server: Some(server),
        gate,
        _other: other,
        other_peer,
    }
}

fn scoped(initial: &LearningIterationSnapshotV1) -> FrozenLearningScopeV2 {
    FrozenLearningScopeV2::freeze(
        &initial.request,
        &initial.owners,
        LearningUpdateScopeV2::Cell,
        Digest32::of_bytes(b"same-actor-framing-component-rule"),
    )
    .unwrap()
}

fn backend(
    store: Arc<FileCas>,
    initial: &LearningIterationSnapshotV1,
    scope: FrozenLearningScopeV2,
) -> LearningIterationCheckpointOwnerV1 {
    LearningIterationCheckpointOwnerV1::from_research_store_scoped_v2(
        store,
        support::OWNER.into(),
        initial.request.clone(),
        initial.owners.clone(),
        scope,
    )
    .unwrap()
}

fn vacant(
    path: &std::path::Path,
    initial: &LearningIterationSnapshotV1,
    scope: &FrozenLearningScopeV2,
) -> Arc<FileCas> {
    Arc::new(
        FileCas::create(
            path,
            &LearningIterationCheckpointRecordV1::vacant_scoped_v2(
                initial.request.clone(),
                initial.owners.clone(),
                scope,
            )
            .unwrap(),
        )
        .unwrap(),
    )
}

fn closed(fixture: &mut PhaseClient) {
    assert!(fixture.gate.require_open().is_err());
    assert_eq!(fixture.other_peer.read(&mut [0]).unwrap(), 0);
}

#[tokio::test]
async fn phase_learning_success_keeps_lane_but_wrong_scope_closes_all_lanes()
-> anyhow::Result<()> {
    let history = snapshots(Decision::EvaluatedNoUpdate)?;
    let initial = &history[0];
    let scope = scoped(initial);
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("original");
    let store = vacant(&path, initial, &scope);
    let original = std::fs::read(&path)?;
    let mut fixture = phase_client(initial, scope.clone());
    let worker = serve(
        fixture.server.take().unwrap(),
        backend(store.clone(), initial, scope),
    );
    assert_eq!(fixture.client.restore(&initial.request).await?, None);
    assert!(fixture.gate.require_open().is_ok());
    let mut wrong = initial.request.clone();
    wrong.operation_id = codex_hepta_types::StableId::new("foreign-phase-request")?;
    assert_eq!(fixture.client.restore(&wrong).await, Err(Error::WrongScope));
    closed(&mut fixture);
    assert_eq!(
        fixture.client.restore(&initial.request).await,
        Err(Error::Store(AuthorityTrustError::Unavailable))
    );
    worker.join().unwrap()?;
    assert_eq!(store.commits.load(Ordering::SeqCst), 0);
    assert_eq!(std::fs::read(&path)?, original);
    Ok(())
}

